import {catalog,byId,CATEGORIES,makePart,newId,pinsOf,pinKey,engineering,parseValue,VALUE_LABELS} from './catalog.js';
import {symbol,esc} from './symbols.js';
import {Simulator,buildNets,exportSpice} from './engine.js';
import {pcbSVG,pcbPads,padsFor,runDRC,exportKiCad,exportGerber,exportDrill} from './pcb.js';
import {Board3D} from './view3d.js';
import {compileFirmware} from './firmware.js';
import {example,emptyProject,EXAMPLES} from './examples.js';
const $=id=>document.getElementById(id),all=q=>[...document.querySelectorAll(q)],uid=newId,clone=x=>JSON.parse(JSON.stringify(x));
const paths={search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',undo:'M8 4 3 9l5 5M3 9h10a7 7 0 0 1 0 14',redo:'M16 4l5 5-5 5m5-5H11a7 7 0 0 0 0 14',left:'M5 3v5h5M5 8a8 8 0 1 1-1 9',right:'M19 3v5h-5m5 0a8 8 0 1 0 1 9',copy:'M8 8h13v13H8ZM3 16V3h13',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',cursor:'M5 3l14 10-7 1-3 7Z',wire:'M4 18V6h16M2 16h4v4H2ZM18 4h4v4h-4Z',pan:'M5 12V8a2 2 0 0 1 4 0v4-8a2 2 0 0 1 4 0v8-6a2 2 0 0 1 4 0v6-3a2 2 0 0 1 4 0v7c0 4-3 6-7 6h-2c-4 0-6-3-8-6l-1-2a2 2 0 0 1 2-2l4 4',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6M10 15v6'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.help}"/></svg>`;
for(const [id,name]of Object.entries({'theme-btn':'sun','help-btn':'help','search-icon':'search','undo-btn':'undo','redo-btn':'redo','rotate-left-btn':'left','rotate-right-btn':'right','duplicate-btn':'copy','delete-btn':'trash','settings-btn':'settings'}))$(id).innerHTML=icon(name);
let project=example(),view='schematic',tool='select',category='All components',selected=null,placing=null,route=null,routeFlip=false,wireColor='#7bdcba',layer='F.Cu',ratsnest=true,undoStack=[],redoStack=[],drag=null,space=false,sim=null,running=false,samples=[],lastFrame=0,user=null,cloudId=null,toastTimer=null,dirtyTimer=null;
function loadFavorites(){try{return new Set(JSON.parse(localStorage.getItem('ome-favorites')||'[]'))}catch{return new Set()}}
let camera={x:80,y:100,w:1000,h:650},scopeChannels=[],favorites=loadFavorites();
const three=new Board3D($('three-view'));
try{const saved=localStorage.getItem('ome-workspace');if(saved)project=validateProject(JSON.parse(saved));}catch{toast('Your saved workspace could not be loaded. A fresh example is open.',true)}
document.documentElement.dataset.theme=localStorage.getItem('ome-theme')||'dark';
function toast(text,error=false){clearTimeout(toastTimer);$('toast').textContent=text;$('toast').className='toast'+(error?' error':'');$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,error?8000:4200);}
function modal(title,html){$('modal-title').textContent=title;$('modal-body').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
function closeModal(){$('modal').close();if(['/signin','/signup'].includes(location.pathname))history.replaceState({},'','/')}
$('modal-close').onclick=closeModal;$('modal').addEventListener('cancel',e=>{e.preventDefault();closeModal()});
function checkpoint(){undoStack.push(clone(project));if(undoStack.length>70)undoStack.shift();redoStack=[];}
function persist(){clearTimeout(dirtyTimer);$('save-state').textContent='Saving locally…';dirtyTimer=setTimeout(()=>{try{localStorage.setItem('ome-workspace',JSON.stringify(project));$('save-state').textContent=user?'Local autosave · account save is manual':'Local workspace · autosaved'}catch{toast('Browser storage is full. Export your project to keep a copy.',true);$('save-state').textContent='Local save failed'}},250)}
function stop(){running=false;$('run-btn').classList.remove('running');$('run-btn').innerHTML='<span>▶</span> Run simulation';$('wave-state').textContent=sim?'PAUSED':'READY';if(sim)$('simulation-status').textContent='Simulation paused';}
function invalidate(){stop();sim=null;samples=[];scopeChannels=[];drawScope();$('simulation-status').textContent='Circuit changed · ready to simulate';$('sim-time').textContent='t = 0.000 s';$('simulation-dot').style.background='';}
function changed({topology=false,reset=true}={}){if(topology)syncCopperNets();if(reset)invalidate();persist();render();}
function syncCopperNets(){const nets=buildNets(project);let map={...nets.nodes};for(let n=0;n<project.traces.length+1;n++)for(const t of project.traces){if(map[t.a]!==undefined)map[t.b]=map[t.a];else if(map[t.b]!==undefined)map[t.a]=map[t.b];}for(const t of project.traces)if(map[t.a]!==undefined)t.net=map[t.a];for(const v of project.vias)if(map['via:'+v.id]!==undefined)v.net=map['via:'+v.id];}
function validateProject(p){if(!p||p.format!=='ome-project'||p.version!==1||!Array.isArray(p.parts)||p.parts.length>150||!Array.isArray(p.wires)||p.wires.length>800)throw Error('Invalid or oversized OME project');if(typeof p.name!=='string'||p.name.length>100)throw Error('Invalid project name');const ids=new Set(),pins=new Set();for(const x of p.parts){if(!byId[x.type]||typeof x.id!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(x.id)||ids.has(x.id))throw Error('Unknown component or duplicate identifier');ids.add(x.id);if(![x.x,x.y,x.rotation||0].every(Number.isFinite))throw Error('Invalid component position');x.values={...byId[x.type].values,...x.values};for(const [key,v]of Object.entries(x.values))if(typeof v!=='number'||!Number.isFinite(v)||Math.abs(v)>1e12)throw Error('Invalid component value');if(x.firmware&&String(x.firmware).length>20000)throw Error('Firmware is too long');x.footprint||={x:x.x,y:x.y,rotation:0};if(![x.footprint.x,x.footprint.y,x.footprint.rotation||0].every(Number.isFinite))throw Error('Invalid footprint');for(const pin of byId[x.type].pins)pins.add(pinKey(x,pin));}
 p.wires.forEach(w=>{if(typeof w.id!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(w.id))throw Error('Invalid wire identifier');if(!pins.has(w.a)||!pins.has(w.b)||!Array.isArray(w.points)||w.points.length>200||w.points.some(pt=>![pt.x,pt.y].every(Number.isFinite)))throw Error('Invalid wire');w.color=/^#[0-9a-f]{6}$/i.test(w.color)?w.color:'#7bdcba';});
 p.board={...emptyProject().board,...p.board};for(const [k,min,max]of [['width',200,4000],['height',200,4000],['clearance',.1,5],['minWidth',.1,5]])if(!Number.isFinite(p.board[k])||p.board[k]<min||p.board[k]>max)throw Error('Invalid board settings');
 p.settings={...emptyProject().settings,...p.settings};if(!Number.isFinite(p.settings.dt)||p.settings.dt<1e-7||p.settings.dt>1||!Number.isFinite(p.settings.stepsPerFrame)||p.settings.stepsPerFrame<1||p.settings.stepsPerFrame>100||!Number.isFinite(p.settings.window)||p.settings.window<1e-6||p.settings.window>1000)throw Error('Invalid simulation settings');
 p.traces||=[];p.vias||=[];if(p.traces.length>1000||p.vias.length>1000)throw Error('PCB route limit exceeded');for(const t of p.traces){if(typeof t.id!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(t.id)||typeof t.a!=='string'||typeof t.b!=='string')throw Error('Invalid trace identifier');if(!Array.isArray(t.points)||t.points.length<2||t.points.length>200||!['F.Cu','B.Cu'].includes(t.layer)||!Number.isFinite(t.width)||t.width<.1||t.width>5||!Number.isInteger(t.net)||t.points.some(a=>![a.x,a.y].every(Number.isFinite)))throw Error('Invalid PCB trace');}for(const v of p.vias)if(typeof v.id!=='string'||!/^[a-zA-Z0-9_-]{1,80}$/.test(v.id)||![v.x,v.y].every(Number.isFinite)||!Number.isInteger(v.net))throw Error('Invalid via');return p;}
function renderLibrary(){const query=$('component-search').value.trim().toLowerCase();$('catalog-count').textContent=catalog.length;$('categories').innerHTML=CATEGORIES.map(c=>`<button data-category="${esc(c)}" class="${category===c?'active':''}">${esc(c==='All components'?'All':c)}</button>`).join('');const items=catalog.filter(c=>(category==='All components'||category==='Favorites'&&favorites.has(c.id)||c.category===category)&&(!query||(c.name+' '+c.kind+' '+c.id).toLowerCase().includes(query)));$('results-count').textContent=items.length;$('category-label').textContent=category.toUpperCase();$('component-list').innerHTML=items.map(c=>`<button class="component-card" data-add="${c.id}" title="Place ${esc(c.name)} · ${c.model}"><span class="component-icon">${symbol({type:c.id,values:c.values},{mini:true})}</span><span><span class="component-name">${esc(c.name)}</span><span class="component-meta">${c.model==='layout-only'?'LAYOUT ONLY':c.model==='gpio-vm'?'GPIO FIRMWARE SUBSET':c.category.toUpperCase()}</span></span><span class="add">+</span></button>`).join('')||'<div class="empty-library">No matching components.<br>Try a device family or function.</div>';}
$('component-search').oninput=renderLibrary;$('categories').onclick=e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;renderLibrary()}};
$('component-list').onclick=e=>{const b=e.target.closest('[data-add]');if(b){if(view==='3d')setView('schematic');placing=makePart(b.dataset.add,0,0);selected=null;route=null;tool='select';renderTools();renderInspector();$('placing-banner').textContent=`Place ${byId[placing.type].name} · click workspace · R rotates · Esc cancels`;$('placing-banner').hidden=false;}};
function renderTools(){$('tools').innerHTML=[['select','cursor','Select (Esc)'],['wire','wire',view==='pcb'?'Route track (W)':'Draw wire (W)'],['pan','pan','Pan workspace (H / Space)']].map(([id,ico,title])=>`<button data-tool="${id}" class="icon-btn ${tool===id?'active':''}" title="${title}" aria-label="${title}">${icon(ico)}</button>`).join('');}
$('tools').onclick=e=>{const b=e.target.closest('[data-tool]');if(b){tool=b.dataset.tool;placing=null;route=null;$('placing-banner').hidden=true;renderTools();renderInspector();renderScene();}};
function refFor(type){const k=byId[type].kind,prefix=k==='resistor'?'R':k==='capacitor'?'C':k==='inductor'?'L':k==='ground'?'G':k==='led'||k==='diode'?'D':['voltage','sine','square'].includes(k)?'V':k==='scope'?'CH':['npn','pnp','nmos','pmos'].includes(k)?'Q':'U';let n=1;while(project.parts.some(p=>p.ref===prefix+n))n++;return prefix+n;}
function endpoint(key){const [id,...rest]=key.split(':');const p=project.parts.find(p=>p.id===id);return p?pinsOf(p).find(p=>p.id===rest.join(':')):null;}
function pcbEndpoint(key){if(key.startsWith('via:'))return project.vias.find(v=>v.id===key.slice(4));return pcbPads(project).find(p=>p.key===key);}
function tail(a,b){if(!a)return [];if(Math.abs(a.x-b.x)<.1||Math.abs(a.y-b.y)<.1)return [b];return routeFlip?[{x:a.x,y:b.y},b]:[{x:b.x,y:a.y},b];}
function wirePoints(w){const a=endpoint(w.a),b=endpoint(w.b);if(!a||!b)return [];return [a,...w.points,...tail(w.points.at(-1)||a,b)];}
function renderScene(){if(view==='3d'){three.setProject(project);return;}const scene=$('scene');if(view==='pcb')scene.innerHTML=pcbSVG(project,selected,layer,ratsnest);else{scene.innerHTML=project.wires.map(w=>{const pts=wirePoints(w).map(p=>p.x+','+p.y).join(' ');return `<g data-wire="${w.id}"><polyline points="${pts}" class="wire-hit"/><polyline points="${pts}" class="wire ${selected===w.id?'selected':''}" stroke="${w.color}"/></g>`}).join('')+project.parts.map(p=>symbol(p,{selected:selected===p.id,current:sim?.currents[p.id]||0})).join('');const counts={};for(const w of project.wires){counts[w.a]=(counts[w.a]||0)+1;counts[w.b]=(counts[w.b]||0)+1}for(const [key,num]of Object.entries(counts))if(num>1){const pt=endpoint(key);if(pt)scene.innerHTML+=`<circle class="wire-junction" cx="${pt.x}" cy="${pt.y}" r="4"/>`;}}
 if(route&&route.cursor){const pts=[...route.points,...tail(route.points.at(-1),route.cursor)];scene.innerHTML+=`<polyline class="wire-draft" points="${pts.map(p=>p.x+','+p.y).join(' ')}"/>`;}
 if(placing&&placing.x&&view==='schematic')scene.innerHTML+=`<g class="ghost" opacity=".55" pointer-events="none">${symbol(placing)}</g>`;
 $('undo-btn').disabled=!undoStack.length;$('redo-btn').disabled=!redoStack.length;$('delete-btn').disabled=!selected;$('duplicate-btn').disabled=!project.parts.some(p=>p.id===selected);
}
function render(){ $('project-name').value=project.name;renderScene();renderInspector();renderSummary();renderTools();}
function renderSummary(){const supported=project.parts.filter(p=>byId[p.type].model!=='layout-only').length;$('project-summary').innerHTML=`<h3>WORKSPACE OVERVIEW</h3><div class="summary-row"><span>Components</span><strong>${project.parts.length}</strong></div><div class="summary-row"><span>Wires / PCB traces</span><strong>${project.wires.length} / ${project.traces.length}</strong></div><div class="summary-row"><span>Electrical models</span><strong>${supported} / ${project.parts.length}</strong></div><div class="summary-row"><span>Timestep</span><strong>${engineering(project.settings.dt,'s')}</strong></div>`;}
function renderInspector(){const p=project.parts.find(p=>p.id===selected),w=project.wires.find(w=>w.id===selected),tr=project.traces.find(w=>w.id===selected);let html='';
 if(route||tool==='wire'){html=`<div class="inspector-kicker">${view==='pcb'?'COPPER ROUTING':'WIRE ROUTING'}</div><div class="empty-inspector"><h3>Make a connection</h3><p>Click a ${view==='pcb'?'pad':'pin'} to start. Click the workspace to place bends, then click the destination ${view==='pcb'?'pad':'pin'}.</p></div><button class="inspector-action" id="bend-toggle">Change bend direction <span>X</span></button><div class="field-note">← / → choose the first bend direction. Backspace removes a bend. Esc cancels.${view==='pcb'?' V inserts a via and switches copper layers.':''}</div>`;}
 else if(p){const c=byId[p.type],k=c.kind;html=`<div class="inspector-kicker">SELECTED COMPONENT</div><div class="selected-title"><div class="large-icon">${symbol(p,{mini:true})}</div><div><h3>${esc(c.name)}</h3><span>${esc(p.ref)} · ${esc(c.category)}</span></div></div><span class="model-badge ${c.model==='layout-only'?'warning':''}">${c.model==='layout-only'?'LAYOUT ONLY · NOT SIMULATED':c.model==='gpio-vm'?'GPIO FIRMWARE SUBSET':'IDEALIZED ELECTRICAL MODEL'}</span><label class="field"><span>Reference</span><input id="part-ref" value="${esc(p.ref)}" maxlength="30"></label>${view==='pcb'?'<div class="info-box">Generic through-hole footprint. Verify pad labels and dimensions before manufacture.</div>':''}`;
 html+=Object.entries(p.values).map(([key,value])=>`<label class="field"><span>${esc(VALUE_LABELS[key]||key)}</span><input data-value="${esc(key)}" value="${value}" inputmode="decimal" aria-label="${esc(VALUE_LABELS[key]||key)}"></label>`).join('');const pos=view==='pcb'?p.footprint:p;html+=`<div class="field-row"><label class="field"><span>X ${view==='pcb'?'(mm)':'(grid)'}</span><input data-position="x" value="${Number((pos.x/(view==='pcb'?10:1)).toFixed(2))}"></label><label class="field"><span>Y ${view==='pcb'?'(mm)':'(grid)'}</span><input data-position="y" value="${Number((pos.y/(view==='pcb'?10:1)).toFixed(2))}"></label></div>`;
 html+='<button class="inspector-action" id="apply-properties">Apply properties <span>↵</span></button>';if(c.model==='gpio-vm')html+='<button class="inspector-action" id="firmware-btn">Edit GPIO firmware <span>↗</span></button>';if(['logic-input','switch','digital-sensor'].includes(k))html+='<button class="inspector-action" id="toggle-btn">Toggle state <span>⇄</span></button>';
 if(sim){const val=byId[p.type].pins.length>=2?sim.v(p,byId[p.type].pins[0].id)-sim.v(p,byId[p.type].pins[1].id):0;if(['voltmeter','scope'].includes(k))html+=`<div class="readout"><span>DIFFERENTIAL VOLTAGE</span><b>${engineering(val,'V')}</b></div>`;if(k==='ammeter')html+=`<div class="readout"><span>BRANCH CURRENT</span><b>${engineering(sim.currents[p.id],'A')}</b></div>`;html+='<div class="inspector-kicker">LIVE PIN VOLTAGES</div><div class="pin-table">'+c.pins.map(pin=>`<div><span>${esc(pin.id)}</span><span>${engineering(sim.v(p,pin.id),'V')}</span></div>`).join('')+'</div>';}
 html+=`<hr class="section-rule"><button class="inspector-action" id="favorite-btn">${favorites.has(p.type)?'Remove favorite':'Add to favorites'} <span>☆</span></button><p class="field-note">${esc(c.description)}</p>`;
 }else if(w||tr){const target=w||tr;html=`<div class="inspector-kicker">${w?'SCHEMATIC WIRE':'PCB TRACK'}</div><div class="selected-title"><h3>${esc(target.a)} → ${esc(target.b)}</h3></div>`;if(w)html+='<p class="field-note">Wire color</p>'+colorPicker(w.color);else html+=`<label class="field"><span>Width (mm)</span><input id="selected-width" type="number" value="${tr.width}" step=".05" min=".15" max="5"></label><label class="field"><span>Copper layer</span><select id="selected-layer"><option ${tr.layer==='F.Cu'?'selected':''}>F.Cu</option><option ${tr.layer==='B.Cu'?'selected':''}>B.Cu</option></select></label><p class="field-note">Net ${tr.net} · ${tr.points.length-1} segments</p>`;html+='<button class="inspector-action" id="remove-bends-btn">Remove intermediate bends <span>⌫</span></button>';
 }else html=`<div class="empty-inspector"><div class="inspector-kicker">YOUR IDEAS, CONNECTED</div><h3>A little curiosity.<br>A whole open lab.</h3><p>Build a circuit, see how it behaves, then take it all the way to a board.</p><div class="getting-started"><div><b>01</b> Choose a component</div><div><b>02</b> Connect its pins</div><div><b>03</b> Run & inspect waveforms</div></div><hr class="section-rule"><p>Click any component to adjust values, inspect pin voltages, or edit firmware.</p><button class="inspector-action" id="inspector-examples">Explore starter circuits <span>↗</span></button><div class="inspector-kicker">WIRE PALETTE</div>${colorPicker(wireColor)}<p class="field-note">Crossing wires do not connect. Start or end at the same pin to join a net.</p></div>`;
 $('inspector').innerHTML=html;
 if($('bend-toggle'))$('bend-toggle').onclick=()=>{routeFlip=!routeFlip;renderScene()};if($('inspector-examples'))$('inspector-examples').onclick=showExamples;
 if(p){$('apply-properties').onclick=()=>{try{const updates={};for(const el of all('[data-value]')){const n=parseValue(el.value),key=el.dataset.value;if(!Number.isFinite(n)||Math.abs(n)>1e12||(!['temperature','voltage','current','offset','phase','low','initial'].includes(key)&&n<0)||(['capacitance','inductance','coilResistance','r25','resistanceAt10Lux'].includes(key)&&n===0))throw Error('Enter valid component values; SI prefixes are supported.');updates[key]=n;}const positions={};for(const el of all('[data-position]')){const n=Number(el.value);if(!Number.isFinite(n))throw Error('Invalid position');positions[el.dataset.position]=n*(view==='pcb'?10:1);}checkpoint();Object.assign(p.values,updates);p.ref=$('part-ref').value;Object.assign(view==='pcb'?p.footprint:p,positions);if(view==='pcb')followPads(p);changed({reset:view!=='pcb'});toast('Component properties applied.');}catch(e){toast(e.message,true)}};all('#inspector input').forEach(el=>el.onkeydown=e=>{if(e.key==='Enter'){$('apply-properties').click();e.preventDefault();}});$('part-ref').onchange=e=>{checkpoint();p.ref=e.target.value;changed({reset:false})};all('[data-value]').forEach(el=>el.onchange=()=>{const n=parseValue(el.value),key=el.dataset.value;if(!Number.isFinite(n)||Math.abs(n)>1e12||(!['temperature','voltage','current','offset','phase','low','initial'].includes(key)&&n<0)||(['capacitance','inductance','coilResistance','r25','resistanceAt10Lux'].includes(key)&&n===0)){toast('Enter a valid value. SI prefixes work: 10k, 100n, 4.7u.',true);renderInspector();return}checkpoint();p.values[key]=n;changed()});all('[data-position]').forEach(el=>el.onchange=()=>{const n=Number(el.value);if(!Number.isFinite(n))return;checkpoint();(view==='pcb'?p.footprint:p)[el.dataset.position]=n*(view==='pcb'?10:1);if(view==='pcb')followPads(p);changed({reset:view!=='pcb'})});if($('firmware-btn'))$('firmware-btn').onclick=()=>showFirmware(p);if($('toggle-btn'))$('toggle-btn').onclick=()=>togglePart(p);$('favorite-btn').onclick=()=>{favorites.has(p.type)?favorites.delete(p.type):favorites.add(p.type);localStorage.setItem('ome-favorites',JSON.stringify([...favorites]));renderLibrary();renderInspector()};}
 all('[data-color]').forEach(el=>el.onclick=()=>{wireColor=el.dataset.color;if(w){checkpoint();w.color=wireColor;changed({reset:false})}else renderInspector()});
 if(tr){$('selected-width').onchange=e=>{const n=Number(e.target.value);if(n<.1||n>5)return;checkpoint();tr.width=n;changed({reset:false})};$('selected-layer').onchange=e=>{checkpoint();tr.layer=e.target.value;changed({reset:false})};}
 if($('remove-bends-btn'))$('remove-bends-btn').onclick=()=>{checkpoint();if(w)w.points=[];else tr.points=[tr.points[0],tr.points.at(-1)];changed({reset:false})};
}
function colorPicker(color){return `<div class="color-options">${['#7bdcba','#e9bc74','#76b8ed','#e8889b','#bd9cf0','#eeeeee','#ef815a'].map(c=>`<button data-color="${c}" title="${c}" aria-label="Wire color ${c}" style="background:${c}" class="${c===color?'active':''}"></button>`).join('')}</div>`;}
function togglePart(p){const kind=byId[p.type].kind,key=kind==='switch'?'closed':kind==='digital-sensor'?'active':'state';checkpoint();p.values[key]=p.values[key]?0:1;const was=running;changed();if(was)startSim();}
function point(e,snap=true){const r=$('editor').getBoundingClientRect(),p={x:camera.x+(e.clientX-r.left)/r.width*camera.w,y:camera.y+(e.clientY-r.top)/r.height*camera.h};const grid=view==='pcb'?5:20;return snap?{x:Math.round(p.x/grid)*grid,y:Math.round(p.y/grid)*grid}:p;}
function updateCamera(){const r=$('editor-area').getBoundingClientRect();camera.h=camera.w*r.height/Math.max(1,r.width);$('editor').setAttribute('viewBox',`${camera.x} ${camera.y} ${camera.w} ${camera.h}`);$('zoom-reset').textContent=Math.round(1000/camera.w*100)+'%';}
function fit(){if(view==='3d'){three.zoom=1;three.yaw=-.35;three.pitch=.9;three.render();return}const r=$('editor-area').getBoundingClientRect();let xs=[],ys=[];if(view==='pcb'){xs=[-40,project.board.width+40];ys=[-40,project.board.height+40]}else{for(const p of project.parts){xs.push(p.x-100,p.x+100);const h=(byId[p.type].boardHeight||90)/2;ys.push(p.y-h-60,p.y+h+80)}}if(!xs.length){camera={x:0,y:0,w:1000,h:600};updateCamera();return}const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),width=maxX-minX,height=maxY-minY;camera.w=Math.max(width,height*r.width/Math.max(1,r.height))*1.08;camera.h=camera.w*r.height/Math.max(1,r.width);camera.x=(minX+maxX-camera.w)/2;camera.y=(minY+maxY-camera.h)/2;updateCamera();}
function zoom(factor,anchor){if(view==='3d'){three.zoom=Math.max(.35,Math.min(3,three.zoom/factor));three.render();return}const oldW=camera.w,oldH=camera.h;const center=anchor||{x:camera.x+camera.w/2,y:camera.y+camera.h/2};camera.w=Math.max(180,Math.min(7000,camera.w*factor));updateCamera();camera.x=center.x-(center.x-camera.x)*camera.w/oldW;camera.y=center.y-(center.y-camera.y)*camera.h/oldH;updateCamera();}
$('zoom-in').onclick=()=>zoom(.8);$('zoom-out').onclick=()=>zoom(1.25);$('zoom-reset').onclick=fit;$('fit-btn').onclick=fit;
function setView(v){route=null;placing=null;view=v;selected=null;$('placing-banner').hidden=true;$('editor').toggleAttribute('hidden',v==='3d');$('three-view').hidden=v!=='3d';$('board-options').hidden=v!=='pcb';$('view-3d-label').hidden=v!=='3d';$('workspace-label').innerHTML=`<span class="status-dot"></span>${v==='schematic'?'SCHEMATIC EDITOR':v==='pcb'?'PCB LAYOUT EDITOR':'3D BOARD VIEWER'} <span class="label-divider">/</span> ${v==='schematic'?'GRID 20':v==='pcb'?'GRID 0.5 mm':'ORBIT CAMERA'}`;$('workspace-tip').textContent=v==='pcb'?'Click pads to route · V inserts via · drag bodies to move footprints':v==='3d'?'Generic bodies · inspect dimensions before manufacture':'Crossing wires do not connect · connect at pins';all('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);b.setAttribute('aria-selected',String(b.dataset.view===v))});render();fit();if(v==='3d')three.setProject(project);}
all('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
function beginRoute(key){const ep=view==='pcb'?pcbEndpoint(key):endpoint(key);if(!ep)return;route={a:key,points:[{x:ep.x,y:ep.y}],cursor:{x:ep.x,y:ep.y},net:view==='pcb'?ep.net:undefined,layer};selected=null;tool='wire';renderTools();renderInspector();$('placing-banner').textContent='Click to add bends · X flips bend · Esc cancels'+(view==='pcb'?' · V adds via':'');$('placing-banner').hidden=false;}
function finishRoute(key){if(key===route.a){toast('Choose a different pin or pad.');return}const ep=view==='pcb'?pcbEndpoint(key):endpoint(key);if(!ep)return;if(view==='pcb'&&ep.net!==route.net){toast('These pads are on different schematic nets. Change the schematic connection first.',true);return}checkpoint();const points=[...route.points,...tail(route.points.at(-1),ep)].filter((p,i,a)=>!i||p.x!==a[i-1].x||p.y!==a[i-1].y);const id=uid();if(view==='pcb')project.traces.push({id,a:route.a,b:key,net:route.net,layer:route.layer,width:Number($('trace-width').value)||.4,points});else project.wires.push({id,a:route.a,b:key,color:wireColor,points:points.slice(1,-1)});route=null;selected=id;tool='select';$('placing-banner').hidden=true;changed({topology:view==='schematic',reset:view==='schematic'});}
function addVia(){if(view!=='pcb'||!route||!route.cursor)return;const v={id:uid(),x:route.cursor.x,y:route.cursor.y,net:route.net};checkpoint();const points=[...route.points,...tail(route.points.at(-1),v)];project.vias.push(v);project.traces.push({id:uid(),a:route.a,b:'via:'+v.id,net:route.net,points,layer:route.layer,width:Number($('trace-width').value)||.4});layer=layer==='F.Cu'?'B.Cu':'F.Cu';$('copper-layer').value=layer;route={a:'via:'+v.id,net:v.net,points:[{x:v.x,y:v.y}],cursor:{x:v.x,y:v.y},layer};persist();renderScene();renderSummary();}
$('editor').addEventListener('pointerdown',e=>{if(e.button===2)return;const pt=point(e),raw=point(e,false);$('editor').focus();$('editor').setPointerCapture(e.pointerId);
 if(e.button===1||space||tool==='pan'){drag={kind:'pan',screen:{x:e.clientX,y:e.clientY},cam:{...camera}};e.preventDefault();return}
 if(placing){if(project.parts.length>=150){toast('This edition supports up to 150 placed parts per project.',true);return}checkpoint();const c=clone(placing);c.id=uid();c.ref=refFor(c.type);if(view==='pcb'){c.x=200+(project.parts.length%5)*160;c.y=200+Math.floor(project.parts.length/5)*130;c.footprint={x:pt.x,y:pt.y,rotation:c.rotation};}else{c.x=pt.x;c.y=pt.y;c.footprint={x:150+(project.parts.length%4)*250,y:150+Math.floor(project.parts.length/4)*180,rotation:c.rotation}}project.parts.push(c);selected=c.id;placing=null;$('placing-banner').hidden=true;changed({topology:true});return;}
 const pin=e.target.closest(view==='pcb'?'[data-pad]':'[data-pin]'),via=e.target.closest('[data-via]'),key=pin?(view==='pcb'?pin.dataset.pad:pin.dataset.pin):via?'via:'+via.dataset.via:null;
 if(key){if(route)finishRoute(key);else beginRoute(key);return;}
 if(route){route.points.push(...tail(route.points.at(-1),pt));route.cursor=pt;renderScene();return;}
 const partEl=e.target.closest('[data-part]');if(partEl){selected=partEl.dataset.part;const p=project.parts.find(p=>p.id===selected);drag={kind:'part',id:p.id,start:raw,origin:clone(view==='pcb'?p.footprint:p),moved:false};renderScene();renderInspector();return;}
 const wire=e.target.closest('[data-wire]'),trace=e.target.closest('[data-trace]');selected=wire?.dataset.wire||trace?.dataset.trace||null;renderScene();renderInspector();});
$('editor').addEventListener('pointermove',e=>{const p=point(e),raw=point(e,false);$('cursor-position').textContent=`X ${(raw.x/(view==='pcb'?10:1)).toFixed(1)} · Y ${(raw.y/(view==='pcb'?10:1)).toFixed(1)}`;
 if(drag?.kind==='pan'){const r=$('editor').getBoundingClientRect();camera.x=drag.cam.x-(e.clientX-drag.screen.x)/r.width*camera.w;camera.y=drag.cam.y-(e.clientY-drag.screen.y)/r.height*camera.h;updateCamera();return}
 if(drag?.kind==='part'){if(!drag.moved)checkpoint();const part=project.parts.find(p=>p.id===drag.id);if(!part)return;const grid=view==='pcb'?5:20,pos=view==='pcb'?part.footprint:part;pos.x=Math.round((drag.origin.x+raw.x-drag.start.x)/grid)*grid;pos.y=Math.round((drag.origin.y+raw.y-drag.start.y)/grid)*grid;drag.moved=true;if(view==='pcb')followPads(part);renderScene();return;}
 if(placing){placing.x=p.x;placing.y=p.y;renderScene()}if(route){const pin=e.target.closest(view==='pcb'?'[data-pad]':'[data-pin]');const ep=pin?(view==='pcb'?pcbEndpoint(pin.dataset.pad):endpoint(pin.dataset.pin)):null;route.cursor=ep?{x:ep.x,y:ep.y}:p;renderScene();}});
function endDrag(){if(drag?.kind==='part'){if(drag.moved)changed({reset:view!=='pcb'});else renderScene();}drag=null;}
$('editor').addEventListener('pointerup',endDrag);$('editor').addEventListener('pointercancel',endDrag);$('editor').addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(e.deltaY*.001),point(e,false))},{passive:false});$('editor').oncontextmenu=e=>e.preventDefault();
$('editor').ondblclick=e=>{const el=e.target.closest('[data-part]'),p=project.parts.find(p=>p.id===el?.dataset.part);if(p&&['switch','logic-input','digital-sensor'].includes(byId[p.type].kind))togglePart(p);};
function followPads(p){const pads=Object.fromEntries(padsFor(p).map(p=>[p.key,p]));for(const t of project.traces){if(pads[t.a])t.points[0]={x:pads[t.a].x,y:pads[t.a].y};if(pads[t.b])t.points[t.points.length-1]={x:pads[t.b].x,y:pads[t.b].y};}}
function rotate(delta){if(placing){placing.rotation=(placing.rotation+delta+360)%360;renderScene();return}const p=project.parts.find(p=>p.id===selected);if(!p)return;checkpoint();const obj=view==='pcb'?p.footprint:p;obj.rotation=((obj.rotation||0)+delta+360)%360;if(view==='pcb')followPads(p);changed({reset:view!=='pcb'});}
function deleteSelected(){if(!selected)return;checkpoint();const part=project.parts.find(p=>p.id===selected);if(part){project.parts=project.parts.filter(p=>p.id!==selected);project.wires=project.wires.filter(w=>!w.a.startsWith(selected+':')&&!w.b.startsWith(selected+':'));project.traces=project.traces.filter(w=>!w.a.startsWith(selected+':')&&!w.b.startsWith(selected+':'));}else{project.wires=project.wires.filter(w=>w.id!==selected);project.traces=project.traces.filter(w=>w.id!==selected)}selected=null;changed({topology:true});}
