function undo(){if(!undoStack.length)return;redoStack.push(clone(project));project=undoStack.pop();selected=null;route=null;placing=null;changed();}
function redo(){if(!redoStack.length)return;undoStack.push(clone(project));project=redoStack.pop();selected=null;route=null;changed();}
$('undo-btn').onclick=undo;$('redo-btn').onclick=redo;$('rotate-left-btn').onclick=()=>rotate(-90);$('rotate-right-btn').onclick=()=>rotate(90);$('duplicate-btn').onclick=duplicate;$('delete-btn').onclick=deleteSelected;
$('clear-btn').onclick=()=>{modal('Clear this workspace?',`<p class="modal-description">This removes every component, wire, PCB track, and via from the schematic and board. Undo can restore this action.</p><div class="modal-actions"><button id="cancel-clear" class="subtle-btn">Keep circuit</button><button id="confirm-clear" class="primary-btn">Clear all views</button></div>`);$('cancel-clear').onclick=closeModal;$('confirm-clear').onclick=()=>{checkpoint();project.parts=[];project.wires=[];project.traces=[];project.vias=[];selected=null;route=null;placing=null;changed();closeModal();fit();toast('All views cleared. Undo is available.')}};
$('copper-layer').onchange=e=>{layer=e.target.value;if(route)toast('Use V while routing to insert a via and change layers.');renderScene()};$('ratsnest-btn').onclick=()=>{ratsnest=!ratsnest;$('ratsnest-btn').textContent='Ratsnest: '+(ratsnest?'on':'off');renderScene()};
function showDRC(){const issues=runDRC(project);modal('PCB design-rule check',`<p class="modal-description">Checks track width, copper clearances, pad / via collisions, board-edge clearance and endpoint connectivity. Generic footprints still require a datasheet review.</p><div class="info-box ${issues.length?'warn-box':''}">${issues.length?`${issues.filter(i=>i.level==='error').length} errors · ${issues.filter(i=>i.level==='warning').length} unrouted warnings`:'No issues found by the implemented checks.'}</div><ul class="issues-list">${issues.map((i,n)=>`<li data-issue="${n}" class="issue-${i.level}">${i.level==='error'?'●':'○'} ${esc(i.text)}</li>`).join('')}</ul>`);all('[data-issue]').forEach(b=>b.onclick=()=>{selected=issues[Number(b.dataset.issue)].id;closeModal();render()});}
