function initSim(){sim=new Simulator(project,{dt:project.settings.dt});samples=[];scopeChannels=project.parts.filter(p=>['scope','voltmeter','ammeter'].includes(byId[p.type].kind)).slice(0,4).map((p,i)=>({id:p.id,label:p.ref||byId[p.type].name,a:pinKey(p,'1'),b:pinKey(p,'2'),current:byId[p.type].kind==='ammeter',color:['#86e7bf','#e9bc74','#76b8ed','#e8889b'][i]}));$('simulation-dot').style.background='';const maxFreq=Math.max(0,...project.parts.map(p=>p.values.frequency||0));if(maxFreq&&project.settings.dt>1/(maxFreq*30))toast('Timestep is coarse for the fastest source. Choose at least 30 samples per period in settings.',true);if(!scopeChannels.length)toast('Add an oscilloscope probe, voltmeter, or ammeter to record waveforms.');if(sim.diagnostics.length)toast(sim.diagnostics.map(d=>d.text).join(' '),true);}
function sampleStep(){const s=sim.step();const row={t:s.time};for(const ch of scopeChannels)row[ch.id]=ch.current?s.currents[ch.id]||0:(s.voltages[ch.a]||0)-(s.voltages[ch.b]||0);samples.push(row);if(samples.length>5000)samples.splice(0,samples.length-5000);}
function simError(e){stop();$('simulation-status').textContent='Simulation stopped · '+e.message;$('simulation-dot').style.background='var(--red)';$('wave-state').textContent='ERROR';toast(e.message,true);}
function startSim(){try{if(!project.parts.length)throw Error('Place components and connect a ground reference first.');if(!sim)initSim();running=true;$('run-btn').classList.add('running');$('run-btn').innerHTML='<span>Ⅱ</span> Pause simulation';$('wave-state').textContent='RUNNING';$('simulation-status').textContent='Transient simulation · backward Euler';}catch(e){simError(e)}}
$('run-btn').onclick=()=>running?stop():startSim();$('step-btn').onclick=()=>{stop();try{if(!sim)initSim();sampleStep();$('simulation-status').textContent='Single step complete';updateSimUI();}catch(e){simError(e)}};
$('reset-sim-btn').onclick=()=>{invalidate();render();toast('Simulation time and component state reset.');};
function updateSimUI(){$('sim-time').textContent='t = '+(sim?.time||0).toFixed(5)+' s';if(!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))renderInspector();renderScene();drawScope();}
function drawScope(){const c=$('scope-canvas'),r=c.getBoundingClientRect();if(r.width<2||r.height<2)return;const dpr=devicePixelRatio||1;c.width=r.width*dpr;c.height=r.height*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);const W=r.width,H=r.height,pad={l:42,r:12,t:8,b:23},ww=W-pad.l-pad.r,hh=H-pad.t-pad.b;const theme=getComputedStyle(document.documentElement),muted=theme.getPropertyValue('--dim').trim(),grid=theme.getPropertyValue('--border').trim();ctx.font='9px ui-monospace, monospace';ctx.textBaseline='middle';const end=samples.at(-1)?.t||project.settings.window,start=Math.max(0,end-project.settings.window),visible=samples.filter(s=>s.t>=start);let values=visible.flatMap(s=>scopeChannels.map(ch=>s[ch.id]||0)),min=Math.min(0,...values),max=Math.max(1,...values);const range=Math.max(.1,max-min);min-=range*.12;max+=range*.12;
 for(let i=0;i<=4;i++){const y=pad.t+hh*i/4;ctx.strokeStyle=grid;ctx.lineWidth=.5;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(W-pad.r,y);ctx.stroke();ctx.fillStyle=muted;ctx.textAlign='right';ctx.fillText((max-(max-min)*i/4).toFixed(1),pad.l-9,y)}
 for(let i=0;i<=5;i++){const x=pad.l+ww*i/5;ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,H-pad.b);ctx.stroke();ctx.fillStyle=muted;ctx.textAlign='center';ctx.fillText(engineering(start+(Math.max(end-start,project.settings.window))*i/5,'s'),x,H-8)}
 for(const ch of scopeChannels){ctx.beginPath();ctx.strokeStyle=ch.color;ctx.lineWidth=1.8;visible.forEach((s,i)=>{const x=pad.l+(s.t-start)/Math.max(project.settings.window,end-start)*ww,y=pad.t+(max-s[ch.id])/(max-min)*hh;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}
 if(!scopeChannels.length){ctx.textAlign='center';ctx.fillStyle=muted;ctx.fillText('Connect a probe and run to capture a waveform',W/2,H/2)}
 $('scope-legend').innerHTML=scopeChannels.map(ch=>`<span><b style="color:${ch.color}">● ${esc(ch.label)}</b>${ch.current?'CURRENT / A':'VOLTAGE / V'}</span>`).join('')||'<span>TRUE SIMULATED SAMPLES · NO GENERATED DEMO DATA</span>';
 const ch=scopeChannels[0],vv=ch?visible.map(s=>s[ch.id]):[],peak=vv.length?Math.max(...vv)-Math.min(...vv):0,rms=vv.length?Math.sqrt(vv.reduce((n,v)=>n+v*v,0)/vv.length):0;$('scope-measurements').innerHTML=`<div class="measurement"><span>PEAK TO PEAK</span><b>${engineering(peak,ch?.current?'A':'V')}</b></div><div class="measurement"><span>RMS · WINDOW</span><b>${engineering(rms,ch?.current?'A':'V')}</b></div><div class="measurement"><span>SAMPLE PERIOD</span><b>${engineering(project.settings.dt,'s')}</b></div>`;
}
function frame(now){if(running&&now-lastFrame>35){lastFrame=now;try{for(let i=0;i<project.settings.stepsPerFrame;i++)sampleStep();updateSimUI()}catch(e){simError(e)}}requestAnimationFrame(frame)}
function download(name,text,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const basename=()=>project.name.replace(/[^a-zA-Z0-9_-]+/g,'_')||'open_multielectrosim';
function csv(){if(!samples.length){toast('Run a simulation before exporting samples.');return}const rows=['time_s,'+scopeChannels.map(c=>`${c.label}_${c.current?'A':'V'}`).join(','),...samples.map(s=>[s.t,...scopeChannels.map(c=>s[c.id])].join(','))];download(basename()+'_waveforms.csv',rows.join('\n'),'text/csv');}
