function showExamples(){modal('Start with a working circuit',`<p class="modal-description">Explore a tested starter, then change its values and connections. Opening a starter replaces the current workspace; Undo restores it.</p><div class="modal-grid">${EXAMPLES.map(e=>`<button class="example-card" data-example="${e.id}"><span>${e.tag}</span><b>${e.name}</b><small>${e.description}</small></button>`).join('')}<button class="example-card" data-example="empty"><span>YOUR NEXT IDEA</span><b>Empty workbench</b><small>Start from a clean schematic and board.</small></button></div>`);all('[data-example]').forEach(b=>b.onclick=()=>{checkpoint();project=b.dataset.example==='empty'?emptyProject():example(b.dataset.example);cloudId=null;selected=null;route=null;placing=null;changed();closeModal();setView('schematic');toast('Circuit loaded. Click Run simulation to inspect the output.');});}
