function showFirmware(p){stop();modal(`${p.ref} · GPIO firmware editor`,`<p class="modal-description">This executes a safe Arduino-style subset against the circuit GPIO pins. It does not execute .hex/.elf binaries, ESP-IDF, MicroPython, Wi-Fi, Linux or complete Arduino libraries.</p><textarea id="firmware-source" class="firmware-editor" spellcheck="false" aria-label="GPIO firmware source">${esc(p.firmware)}</textarea><p class="field-note">Supported: setup, loop, variables, assignment, if / else, while, arithmetic, pinMode, digitalWrite, digitalRead, analogRead, analogWrite (average voltage), delay, delayMicroseconds, millis, micros, Serial.begin / println. Add delay inside repeating loops. Power VCC and GND. The VM is timestep-quantized.</p><div id="firmware-error" class="form-error"></div><div class="modal-actions"><button id="firmware-serial" class="subtle-btn">Serial output</button><button id="firmware-save" class="primary-btn">Validate & apply</button></div>`);$('firmware-save').onclick=()=>{try{const src=$('firmware-source').value;if(src.length>20000)throw Error('Source limit is 20,000 characters');compileFirmware(src);checkpoint();p.firmware=src;changed();closeModal();toast('Firmware validated and applied. Run the simulation to execute it.');}catch(e){$('firmware-error').textContent=e.message;}};$('firmware-serial').onclick=()=>{const vm=sim?.vms[p.id];toast(vm?.serial.length?vm.serial.slice(-6).join(' | '):'No serial output yet. Run code with Serial.println().');};}
function showSettings(){modal('Simulation & board settings',`<p class="modal-description">A smaller timestep improves transient resolution and increases computation. The waveform shows simulated time; it is independent of wall-clock speed.</p><div class="modal-grid"><label class="field"><span>Simulation timestep (seconds)</span><input id="setting-dt" value="${project.settings.dt}"></label><label class="field"><span>Steps per display frame (1–100)</span><input id="setting-steps" type="number" value="${project.settings.stepsPerFrame}"></label><label class="field"><span>Waveform time window (seconds)</span><input id="setting-window" value="${project.settings.window}"></label><label class="field"><span>Board width (mm, including margin)</span><input id="setting-bw" type="number" value="${project.board.width/10}"></label><label class="field"><span>Board height (mm, including margin)</span><input id="setting-bh" type="number" value="${project.board.height/10}"></label><label class="field"><span>Copper clearance (mm)</span><input id="setting-clearance" type="number" step=".05" value="${project.board.clearance}"></label><label class="field"><span>Minimum track width (mm)</span><input id="setting-width" type="number" step=".05" value="${project.board.minWidth}"></label></div><div class="info-box warn-box">The actual rectangular board outline is inset 2.4 mm on each side. The live 3D view uses generic component bodies, rather than manufacturer CAD models.</div><div id="settings-error" class="form-error"></div><div class="modal-actions"><button id="apply-settings" class="primary-btn">Apply settings</button></div>`);$('apply-settings').onclick=()=>{try{const cp=clone(project);cp.settings={dt:parseValue($('setting-dt').value),stepsPerFrame:Number($('setting-steps').value),window:parseValue($('setting-window').value)};cp.board={width:Number($('setting-bw').value)*10,height:Number($('setting-bh').value)*10,clearance:Number($('setting-clearance').value),minWidth:Number($('setting-width').value)};validateProject(cp);checkpoint();project=cp;changed();closeModal();fit()}catch(e){$('settings-error').textContent=e.message}};}
$('settings-btn').onclick=showSettings;
function showModels(){modal('Simulation model coverage',`<p class="modal-description">${catalog.length} catalog entries. Every component is labeled by its supported behavior. These are educational models, with no claim of complete manufacturer-model coverage.</p><table class="coverage-table"><thead><tr><th>Component family</th><th>Implemented behavior / boundary</th></tr></thead><tbody><tr><td>R, C, L, potentiometer</td><td>Nodal solver; capacitor / inductor backward-Euler companions. Fixed values; no tolerance, thermal drift, saturation or ESR unless explicitly exposed.</td></tr><tr><td>Diodes, LEDs, Zener</td><td>Piecewise-linear forward drop and reverse breakdown. No junction capacitance, reverse recovery, light spectrum or damage model.</td></tr><tr><td>BJT, MOSFET</td><td>Generic simplified low-frequency models. No manufacturer SPICE parameter sets or high-frequency parasitics.</td></tr><tr><td>Op-amps, comparators, relay</td><td>Configurable gain / rails, ideal threshold comparator, coil-resistance and pickup model. No bandwidth, contact bounce, coil inductance or real-device limits.</td></tr><tr><td>Logic gates, mux</td><td>Fixed-point solution within a timestep. No artificial extra step in combinational gate chains. Oscillating loops stop with a diagnostic.</td></tr><tr><td>D flip-flop, counter, 555</td><td>Behavioral edge / latch models, not pin-compatible packaged IC simulation.</td></tr><tr><td>Arduino, ESP32, Pico</td><td>Logical GPIO symbols with a bounded Arduino-style interpreter. No instruction-set or full peripheral emulation. PWM uses an average-voltage model.</td></tr><tr><td>Raspberry Pi computers</td><td>Layout only. No CPU, Linux or firmware execution.</td></tr><tr><td>LDR, thermistors, LM35, TMP36</td><td>Light / temperature transfer functions. Inputs supplied by the user; no spatial or environmental physics.</td></tr><tr><td>HC-SR04</td><td>Trigger / echo pulse timing with user-set distance. Use timestep ≤ 5 µs for short triggers.</td></tr><tr><td>DHT, I2C, GPS, display modules</td><td>Layout-only placeholders, clearly labeled. No fabricated readings or protocol responses.</td></tr><tr><td>PCB / 3D</td><td>Generic through-hole footprints, two copper layers, vias, basic DRC, board export and projected 3D bodies. KiCad native DRC remains necessary.</td></tr></tbody></table><div class="info-box warn-box">Waveforms are computed samples of the implemented models. They are not guaranteed to predict real hardware accurately. Validate critical designs with device datasheets and a verified SPICE model.</div>`);}
$('models-btn').onclick=showModels;
function showHelp(){const rows=[['Search components','/'],['Select / cancel','Esc'],['Wire / route track','W'],['Pan / hold to pan','H / Space'],['Run / pause','Space (tap)'],['Rotate right / left','R / Shift+R'],['Flip route bend','X'],['Bend orientation','← / →'],['Remove last bend','Backspace'],['Via & change layer (PCB)','V'],['Undo / redo','Ctrl+Z / Ctrl+Shift+Z'],['Duplicate','Ctrl+D'],['Delete selected','Delete'],['Fit to view','F'],['Zoom','Scroll / + / −'],['Save project','Ctrl+S'],['Toggle theme','T'],['Open shortcuts','?']];modal('Your workbench, at your fingertips',`<p class="modal-description">Choose a component in the library, then click the workspace to place it. Click a pin to start a wire, click empty space for manual bends, and click another pin to finish. Wires connect at pins; visual crossings do not join. Drag any component body to move it.</p><div class="shortcut-list">${rows.map(r=>`<div>${r[0]} <kbd>${r[1]}</kbd></div>`).join('')}</div><div class="info-box">In PCB layout, route only pads on the same schematic net. Choose F.Cu or B.Cu before routing; press V to place a via and continue on the other layer. Drag footprints, run DRC, then inspect the live 3D board.</div><div class="modal-actions"><button id="help-models" class="subtle-btn">Model coverage</button><button id="help-import" class="subtle-btn">Import project</button></div>`);$('help-models').onclick=showModels;$('help-import').onclick=importProject;}
$('help-btn').onclick=showHelp;$('shortcuts-btn').onclick=showHelp;
function importProject(){const input=document.createElement('input');input.type='file';input.accept='.json,.ome';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{if(file.size>1048576)throw Error('Project file exceeds 1 MB');const p=validateProject(JSON.parse(await file.text()));checkpoint();project=p;cloudId=null;selected=null;route=null;changed();closeModal();setView('schematic');toast('Project imported.')}catch(e){toast(e.message,true)}};input.click();}
function showExport(){modal('Export your work',`<p class="modal-description">Project JSON preserves the full schematic, firmware, PCB, settings and routes. Other formats cover the supported export subset.</p>${[['json','Full editable project','.ome.json · includes schematic, firmware and PCB'],['kicad','KiCad board','.kicad_pcb · self-contained generic footprints, nets, vias and copper'],['gerber-front','Front copper Gerber','.gtl · generic pads and front tracks'],['gerber-back','Back copper Gerber','.gbl · generic pads and back tracks'],['drill','Excellon drill','.drl · component, via and mounting holes'],['spice','SPICE primitive netlist','.cir · R, C, L, DC sources, sine sources; rejects unsupported devices'],['csv','Waveform samples','.csv · recorded voltage / current versus simulated time'],['bom','Bill of materials','.csv · references, names, values, model coverage'],['svg','Schematic drawing','.svg · scalable vector circuit drawing'],['import','Import an existing project','.ome.json · restores a saved workspace']].map(([id,title,desc])=>`<button class="export-choice" data-export="${id}"><b>${title} <span>↗</span></b><small>${desc}</small></button>`).join('')}<div class="info-box warn-box">Gerber and drill exports are partial fabrication aids. They do not include a complete manufacturing job. The KiCad file uses generic footprints: confirm pin numbers, physical dimensions, outline and clearances in KiCad before fabrication.</div>`);all('[data-export]').forEach(b=>b.onclick=()=>{try{const id=b.dataset.export;if(id==='json')download(basename()+'.ome.json',JSON.stringify(project,null,2),'application/json');else if(id==='kicad')download(basename()+'.kicad_pcb',exportKiCad(project));else if(id.startsWith('gerber'))download(basename()+(id==='gerber-front'?'.gtl':'.gbl'),exportGerber(project,id==='gerber-front'?'F.Cu':'B.Cu'));else if(id==='drill')download(basename()+'.drl',exportDrill(project));else if(id==='spice')download(basename()+'.cir',exportSpice(project));else if(id==='csv')csv();else if(id==='bom'){const quote=s=>'"'+String(s).replace(/"/g,'""')+'"';download(basename()+'_BOM.csv',['Reference,Component,Values,Model',...project.parts.map(p=>[p.ref,byId[p.type].name,JSON.stringify(p.values),byId[p.type].model].map(quote).join(','))].join('\n'),'text/csv')}else if(id==='svg'){const drawing=project.parts.map(p=>symbol(p)).join('')+project.wires.map(w=>`<polyline points="${wirePoints(w).map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="${w.color}" stroke-width="2"/>`).join('');download(basename()+'.svg',`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1500 1200"><style>text{font:12px sans-serif;fill:#17382a}.component-symbol{stroke:#17382a;stroke-width:2;fill:white}.component-symbol text{stroke:none;font-size:9px}.part-value{font-size:11px}.pin circle{fill:white;stroke:#287c59}.pin-target,.component-hit{display:none}</style><rect width="1500" height="1200" fill="white"/>${drawing}</svg>`,'image/svg+xml');}else if(id==='import')importProject();}catch(e){toast(e.message,true)}});}
$('export-btn').onclick=showExport;
async function api(url,method='GET',data){const r=await fetch(url,{method,headers:{'Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});const b=await r.json();if(!r.ok)throw Error(b.error||'Request failed');return b;}
function updateUser(){ $('account-btn').textContent=user?user.name+' ▾':'Sign in ↗';$('save-state').textContent=user?'Local autosave · account save is manual':'Local workspace · autosaved';}
function showAuth(signup=false){history.replaceState({},'',signup?'/signup':'/signin');modal(signup?'Create your lab account':'Welcome back to your lab',`<p class="modal-description">Accounts belong to this Open MultiElectrosim server. Guest work autosaves in this browser. Sign in to save separate named projects on the server.</p><form id="auth-form" class="auth-form">${signup?'<label class="field"><span>Your name</span><input name="name" autocomplete="name" maxlength="60" required></label>':''}<label class="field"><span>Email address</span><input name="email" type="email" autocomplete="email" maxlength="254" required></label><label class="field"><span>Password · at least 10 characters</span><input name="password" type="password" minlength="10" maxlength="128" autocomplete="${signup?'new-password':'current-password'}" required></label><div class="form-error" id="auth-error"></div><button id="auth-submit" class="primary-btn" type="submit">${signup?'Create account':'Sign in'}</button><p class="auth-switch">${signup?'Already have an account? <a href="/signin" id="auth-switch">Sign in</a>':'New to the workbench? <a href="/signup" id="auth-switch">Create an account</a>'}</p><p class="field-note">Email is used as your account identifier. Email verification and password recovery are not included in this local edition.</p></form>`);$('auth-switch').onclick=e=>{e.preventDefault();showAuth(!signup)};$('auth-form').onsubmit=async e=>{e.preventDefault();const button=$('auth-submit');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));const r=await api('/api/auth/'+(signup?'signup':'signin'),'POST',data);user=r.user;cloudId=null;updateUser();closeModal();toast('Signed in. Your current workspace is ready to save.');}catch(e){$('auth-error').textContent=e.message}finally{button.disabled=false}};}
async function showAccount(){if(!user){showAuth();return}modal('Your projects',`<p class="modal-description">Signed in as <b>${esc(user.name)}</b> · ${esc(user.email)}. Projects are stored by the local server. Back up the data folder to preserve accounts and saved projects.</p><div class="modal-actions"><button id="account-save" class="primary-btn">Save current project</button><button id="account-signout" class="subtle-btn">Log out</button></div><div id="account-projects"><p class="modal-description">Loading projects…</p></div>`);$('account-save').onclick=saveProject;$('account-signout').onclick=async()=>{try{await api('/api/auth/signout','POST');user=null;cloudId=null;updateUser();closeModal();toast('Logged out. Browser workspace remains available.');}catch(e){toast(e.message,true)}};try{const {projects}=await api('/api/projects');if(!$('account-projects'))return;$('account-projects').innerHTML=projects.map(p=>`<div class="project-row"><div><b>${esc(p.name)}</b><small>${p.parts} components · ${new Date(p.updated).toLocaleString()}</small></div><button class="subtle-btn" data-open-project="${p.id}">Open</button><button class="icon-btn" data-delete-project="${p.id}" aria-label="Delete saved project">✕</button></div>`).join('')||'<div class="info-box">No account projects yet. Save the current workspace to create your first.</div>';all('[data-open-project]').forEach(b=>b.onclick=async()=>{try{const {project:p}=await api('/api/projects/'+b.dataset.openProject);checkpoint();project=validateProject(p);cloudId=b.dataset.openProject;selected=null;changed();closeModal();setView('schematic');toast('Account project opened.')}catch(e){toast(e.message,true)}});all('[data-delete-project]').forEach(b=>b.onclick=()=>{const pid=b.dataset.deleteProject;modal('Delete this saved project?',`<p class="modal-description">This permanently removes this account copy. The currently open workspace is kept.</p><div class="modal-actions"><button id="cancel-delete" class="subtle-btn">Cancel</button><button id="confirm-delete" class="primary-btn">Delete saved copy</button></div>`);$('cancel-delete').onclick=showAccount;$('confirm-delete').onclick=async()=>{try{await api('/api/projects/'+pid,'DELETE');if(cloudId===pid)cloudId=null;showAccount()}catch(e){toast(e.message,true)}};});}catch(e){toast(e.message,true)}}
async function saveProject(){try{if(user){const r=await api('/api/projects'+(cloudId?'/'+cloudId:''),cloudId?'PUT':'POST',project);cloudId=r.id||cloudId;toast('Project saved to your account.');if($('modal').open&&$('account-projects'))showAccount();}else{download(basename()+'.ome.json',JSON.stringify(project,null,2),'application/json');toast('Project exported. Sign in to save named projects on the server.');}persist();}catch(e){toast(e.message,true)}}
$('account-btn').onclick=showAccount;$('save-btn').onclick=saveProject;$('project-name').onchange=e=>{checkpoint();project.name=e.target.value.trim().slice(0,100)||'Untitled circuit';persist()};
function toggleTheme(){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('ome-theme',next);drawScope();three.render()}
$('theme-btn').onclick=toggleTheme;
let spaceStart=0;
document.addEventListener('keydown',e=>{const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName);if(editing||$('modal').open){if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();}return;}if(e.code==='Space'){e.preventDefault();if(!e.repeat){space=true;spaceStart=performance.now()}return;}const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return}if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();return}if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();duplicate();return}
 switch(e.key){case 'Escape':route=null;placing=null;selected=null;tool='select';$('placing-banner').hidden=true;render();break;case '/':e.preventDefault();$('component-search').focus();break;case 'w':case 'W':tool='wire';renderTools();renderInspector();break;case 'h':case 'H':tool='pan';renderTools();break;case 'r':case 'R':rotate(e.shiftKey?-90:90);break;case 'f':case 'F':fit();break;case 't':case 'T':toggleTheme();break;case 'x':case 'X':routeFlip=!routeFlip;renderScene();break;case 'ArrowLeft':if(route){e.preventDefault();routeFlip=true;renderScene()}break;case 'ArrowRight':if(route){e.preventDefault();routeFlip=false;renderScene()}break;case 'v':case 'V':addVia();break;case 'Delete':deleteSelected();break;case 'Backspace':if(route){e.preventDefault();if(route.points.length>1)route.points.pop();renderScene()}else deleteSelected();break;case '+':case '=':zoom(.85);break;case '-':zoom(1.18);break;case '?':showHelp();break;}
});document.addEventListener('keyup',e=>{if(e.code==='Space'){const was=space;space=false;if(was&&performance.now()-spaceStart<200&&!drag&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('modal').open)running?stop():startSim();}});window.addEventListener('blur',()=>{space=false;drag=null});
new ResizeObserver(()=>{updateCamera();drawScope();three.render()}).observe($('editor-area'));new ResizeObserver(drawScope).observe($('scope-canvas'));
renderLibrary();render();requestAnimationFrame(()=>{fit();drawScope()});requestAnimationFrame(frame);
api('/api/auth/me').then(r=>{user=r.user;updateUser();if(location.pathname==='/signup')showAuth(true);else if(location.pathname==='/signin')showAuth(false);}).catch(()=>{if(['/signin','/signup'].includes(location.pathname))showAuth(location.pathname==='/signup');});
